import { useState } from "react";
import { Link, useNavigate } from "react-router-dom"; // أضفنا useNavigate للتوجيه
import api from "../api"; // استيراد ملف axios الذي أعددناه سابقاً

const ROLES = [
  {id:"student", label:"Student",  emoji:"🎓", placeholder:"amira@ifa.edu.dz"},
  {id:"company", label:"Company",  emoji:"🏢", placeholder:"rh@company.com"},
  {id:"admin",   label:"Admin",    emoji:"🏛️", placeholder:"admin@university.dz"},
];

export default function Login() {
  const [role, setRole]       = useState("student");
  const [email, setEmail]     = useState("");
  const [password, setPassword] = useState("");
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading]   = useState(false); // حالة التحميل أثناء الطلب

  const navigate = useNavigate();
  const cfg = ROLES.find(r => r.id === role);

  // --- دالة تسجيل الدخول ---
  const handleLogin = async (e) => {
    e.preventDefault();
    if (!email || !password) {
      alert("Please fill in your credentials");
      return;
    }

    setLoading(true);
    try {
      // إرسال الطلب لـ Django
      const response = await api.post('login/', {
        username: email, // نرسل الإيميل كـ username ليتوافق مع السيرفر
        password: password
      });

      // حفظ التوكين في التخزين المحلي
      localStorage.setItem('access_token', response.data.access);
      localStorage.setItem('refresh_token', response.data.refresh);

      // طلب بيانات الملف الشخصي للتأكد من الدور (Role) المسجل في القاعدة
      const profileRes = await api.get('profile/');
      const userRole = profileRes.data.role.toLowerCase();
      localStorage.setItem('userRole', userRole);

      // التوجيه بناءً على نوع المستخدم
      if (userRole === "student") navigate("/student/dashboard");
      else if (userRole === "company") navigate("/company/dashboard");
      else if (userRole === "admin") navigate("/admin/dashboard");
      else navigate("/dashboard");

    } catch (error) {
      console.error("Login error:", error);
      const msg = error.response?.data?.detail || "Invalid email or password.";
      alert(msg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex bg-[#fdf9f5]">
      {/* Left panel - بقِيَ كما هو للتصميم */}
      <div className="hidden lg:flex lg:w-[52%] bg-slate-900 flex-col relative overflow-hidden">
        <div className="absolute inset-0 dot-grid opacity-40"/>
        <div className="absolute bottom-0 left-0 w-80 h-80 bg-soft/20 rounded-full blur-3xl"/>
        <div className="relative p-10">
          <Link to="/" className="font-syne font-extrabold text-2xl text-white tracking-tight">Stag<span className="text-soft">.</span>io</Link>
        </div>
        <div className="flex-1 flex flex-col justify-center px-12 pb-16 relative">
          <p className="text-xs font-semibold tracking-widest text-soft uppercase mb-4">Welcome back</p>
          <h1 className="font-syne font-extrabold text-white leading-tight mb-5" style={{fontSize:"clamp(2rem,3.5vw,3rem)",letterSpacing:"-1px"}}>
            Your internship<br/>journey starts<br/><span className="text-soft">right here.</span>
          </h1>
          <p className="text-slate-400 font-light leading-relaxed text-sm max-w-sm">Sign in to access offers, manage applications, and track your placement.</p>

          {/* Demo cards */}
          <div className="mt-12 relative h-44">
            <div className="panel-card absolute left-0 top-0 bg-white/10 backdrop-blur-sm border border-white/10 rounded-2xl p-4 w-64">
              <div className="flex items-center gap-3 mb-3">
                <div className="w-8 h-8 bg-soft/30 rounded-lg flex items-center justify-center text-sm">🎓</div>
                <div>
                  <div className="text-xs font-semibold text-white">Amira Benali</div>
                  <div className="text-xs text-slate-400">L3 Informatique · IFA</div>
                </div>
                <span className="ml-auto text-xs text-[#c97168] font-semibold bg-blush/20 px-2 py-0.5 rounded-full">Placed ✓</span>
              </div>
              <div className="flex gap-1.5">
                {["React","Node.js","SQL"].map(t=><span key={t} className="text-xs bg-soft/20 text-soft px-2 py-0.5 rounded-full">{t}</span>)}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Right panel - مع تحديث الفورم والزر */}
      <div className="flex-1 flex flex-col justify-center items-center px-6 py-12">
        <div className="w-full max-w-md">
          <div className="anim-fade-up mb-8">
            <h2 className="font-syne font-extrabold text-slate-900 text-3xl tracking-tight mb-1">Sign in</h2>
            <p className="text-slate-500 text-sm font-light">Don't have an account? <Link to="/register" className="text-[#2E7DF7] font-medium hover:underline">Create one →</Link></p>
          </div>

          {/* Role tabs */}
          <div className="anim-fade-up anim-d1 bg-slate-100 rounded-xl p-1 flex mb-7">
            {ROLES.map(r => (
              <button key={r.id} onClick={() => setRole(r.id)}
                className={`flex-1 flex items-center justify-center gap-1.5 py-2 rounded-lg text-sm font-medium transition-all duration-200 ${role===r.id?"bg-white text-slate-900 shadow-sm":"text-slate-500 hover:text-slate-700"}`}>
                <span>{r.emoji}</span><span>{r.label}</span>
              </button>
            ))}
          </div>

          <form onSubmit={handleLogin} className="space-y-5">
            <div className="anim-fade-up anim-d2">
              <label className="block text-sm font-medium text-slate-700 mb-1.5">Email</label>
              <input 
                type="email" 
                value={email} 
                onChange={e=>setEmail(e.target.value)} 
                placeholder={cfg.placeholder} 
                className="input-field"
                required
              />
            </div>
            <div className="anim-fade-up anim-d3">
              <div className="flex justify-between items-center mb-1.5">
                <label className="text-sm font-medium text-slate-700">Password</label>
                <a href="/" className="text-xs text-[#2E7DF7] hover:underline font-medium">Forgot password?</a>
              </div>
              <div className="relative">
                <input 
                  type={showPass?"text":"password"} 
                  value={password} 
                  onChange={e=>setPassword(e.target.value)} 
                  placeholder="••••••••" 
                  className="input-field pr-11"
                  required
                />
                <button type="button" onClick={()=>setShowPass(!showPass)} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 text-sm">{showPass?"🙈":"👁️"}</button>
              </div>
            </div>
            
            <div className="anim-fade-up anim-d5">
              <button 
                type="submit"
                disabled={loading}
                className={`shimmer-btn w-full text-white font-semibold py-3 rounded-xl text-sm flex justify-center items-center gap-2 ${loading ? 'opacity-70 cursor-not-allowed' : ''}`}
              >
                {loading ? "Signing in..." : "Sign in to Stag.io →"}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}
